      '.elz-seg-btn:hover { color: var(--dsw-alias-label-primary); }',
      '.elz-seg-on { background: var(--dsw-alias-interactive-bg-hover); color: var(--dsw-alias-label-primary); font-weight: 600; }',
      '.elz-card-known { opacity: 0.55; }',
